223:         if ($model === null) return null;
224:         $finishStatus = [
225:             Freespin::STATUS_CANCEL_AUTO,
226:             Freespin::STATUS_CANCEL_ADMIN,
227:             Freespin::STATUS_CANCEL_USER,
228:             Freespin::STATUS_END,
229:             Freespin::STATUS_ERROR
230:         ];
231: 
232:         if (in_array($model->freespin?->status, $finishStatus) || $model->freespin?->valid_until < time()) {
233:             $model->cancelMaxWin();
234:             return null;
235:         }
236: 
237:         return $model;
