331:         $this->finish = true;
332:         $status = $this->save();
333:         if (!$status) {
334:             return false;
335:         }
336: 
337:         $where = array_filter([
338:             'user_id' => $this->user_id,
339:             'active' => true,
340:             'finish' => false,
341:             'user_bonus_id' => $this->user_bonus_id,
