274:             if (!$campingResult) {
275:                 Logger::writeError('createFreeSpin setCamping failed freespin_id:' . $freespin->freespin_id
276:                     . ' bonusId:' . var_export($bonusId, true)
277:                     . ' userUuid:' . $userUuid
278:                     . ' gameUid:' . $gameUid
279:                     . ' currency:' . $currency);
