299:                     if ((int)$freespin->status === self::STATUS_NEW) {
300:                         // Запис лишився NEW: setCamping упав ще до фіксації статусу. При цьому HTTP
301:                         // міг дійти до провайдера й створити кампанію → потенційно осиротілий запис.
