33:     {
34:         $freespinId = Freespin::createFreeSpin(
35:             $this->playerUid,
36:             $this->currency,
37:             $this->gameSlug,
38:             $this->denomination,
39:             $this->betId,
40:             $count,
41:             $this->bonusId,
42:             $this->event
43:         );
44:         // createFreeSpin отвечает false при отказе провайдера или лимита
45:         return $freespinId ? (string)$freespinId : null;
46:     }
